private Task ApplyAsync(IReadOnlyList<AgentPlanStep> next, AgentPlanEdit edit)
{
    switch (edit.Kind)
    {
        case AgentPlanEditKind.Remove:
            _removed = edit.Step; // keep it for the host's own undo
            break;
        case AgentPlanEditKind.Rename:
            _log.WriteLine($"{edit.StepId} -> {edit.Title}");
            break;
    }

    _steps = next;
    return Task.CompletedTask;
}
